<template>
  <main class="quran-page">
    <header class="quran-hero">
      <div class="hero-copy"><div class="hero-icon"><q-icon name="menu_book" size="26px" /></div><div><span>PEMBELAJARAN AL-QUR’AN</span><h1>Hafalan & Murojaah</h1><p>Catat perkembangan hafalan santri secara runtut dan mudah ditinjau.</p></div></div>
      <div class="hero-stats"><div><strong>{{ records.length }}</strong><span>Total setoran</span></div><div><strong>{{ uniqueStudents }}</strong><span>Santri aktif</span></div><div><strong>{{ passedCount }}</strong><span>Lancar</span></div></div>
    </header>

    <q-tabs v-model="tab" dense no-caps align="left" indicator-color="transparent" class="quran-tabs">
      <q-tab name="murajaah" icon="edit_note" label="Catat Murojaah" />
      <q-tab name="history" icon="history" label="Riwayat Hafalan" />
      <q-tab v-if="canImport" name="master" icon="database" label="Master Al-Qur’an" />
    </q-tabs>

    <q-tab-panels v-model="tab" animated class="panels">
      <q-tab-panel name="murajaah" class="panel-reset"><section class="workspace-grid">
        <q-card flat class="surface form-card">
          <div class="card-heading"><div><span>SETORAN BARU</span><h2>Form murojaah</h2></div><q-icon name="auto_stories" /></div>
          <q-form class="murajaah-form" @submit.prevent="saveRecord">
            <div class="field full"><label>Nama santri</label><q-select v-model="form.anggota_id" :options="students" emit-value map-options outlined dense use-input input-debounce="0" :loading="loadingStudents" @filter="filterStudents" :rules="[required]" placeholder="Pilih santri" /></div>
            <div class="field full"><label>Surat</label><q-select v-model="form.surah_number" :options="surahOptions" emit-value map-options outlined dense use-input input-debounce="0" @filter="filterSurahs" :rules="[required]" placeholder="Cari nama surat" @update:model-value="normalizeVerses" /></div>
            <div class="field"><label>Ayat awal</label><q-input v-model.number="form.ayah_start" type="number" min="1" :max="selectedSurah?.ayah_count || 286" outlined dense :rules="verseRules" /></div>
            <div class="field"><label>Ayat akhir</label><q-input v-model.number="form.ayah_end" type="number" :min="form.ayah_start || 1" :max="selectedSurah?.ayah_count || 286" outlined dense :rules="endVerseRules" /></div>
            <div class="field"><label>Tanggal</label><q-input v-model="form.review_date" type="date" outlined dense :rules="[required]" /></div>
            <div class="field"><label>Hasil</label><q-select v-model="form.result" :options="resultOptions" emit-value map-options outlined dense /></div>
            <div class="field full"><label>Catatan pengajar</label><q-input v-model.trim="form.notes" type="textarea" rows="3" outlined placeholder="Contoh: Tajwid baik, perlu mengulang ayat 8" /></div>
            <q-btn type="submit" unelevated no-caps icon="check_circle" label="Simpan murojaah" class="save-btn full" :loading="saving" />
          </q-form>
        </q-card>
        <aside class="side-column"><q-card flat class="surface selection-card"><span>RINGKASAN SETORAN</span><div v-if="selectedSurah" class="surah-preview"><b>{{ selectedSurah.number }}</b><div><strong>{{ selectedSurah.name }}</strong><small>{{ selectedSurah.arabic }} · {{ selectedSurah.ayah_count }} ayat</small></div></div><div v-else class="empty-mini"><q-icon name="bookmark_border" />Pilih surat untuk melihat ringkasan.</div><div v-if="selectedSurah" class="range"><span>Rentang ayat</span><strong>{{ form.ayah_start || 1 }}—{{ form.ayah_end || 1 }}</strong></div></q-card><q-card flat class="tip-card"><q-icon name="lightbulb" /><div><strong>Catat langsung setelah setoran</strong><p>Hasil yang konsisten membantu pengajar menentukan bagian yang perlu diulang.</p></div></q-card></aside>
      </section></q-tab-panel>

      <q-tab-panel name="history" class="panel-reset"><q-card flat class="surface history-card">
        <div class="history-head"><div><span>PERKEMBANGAN SANTRI</span><h2>Riwayat hafalan</h2></div><q-input v-model="search" dense outlined clearable placeholder="Cari santri atau surat"><template #prepend><q-icon name="search" /></template></q-input></div>
        <q-table flat :rows="filteredRecords" :columns="columns" row-key="id" :loading="loadingRecords" :pagination="{ rowsPerPage: 8 }" class="history-table">
          <template #body-cell-student="p"><q-td :props="p"><div class="student-cell"><span>{{ initialsOf(p.row.student_name) }}</span><strong>{{ p.row.student_name }}</strong></div></q-td></template>
          <template #body-cell-surah="p"><q-td :props="p"><strong>{{ surahName(p.row.surah_number) }}</strong><small class="verse-note">Ayat {{ p.row.ayah_start }}—{{ p.row.ayah_end }}</small></q-td></template>
          <template #body-cell-result="p"><q-td :props="p"><q-badge rounded :class="`result-${p.row.result}`">{{ resultLabel(p.row.result) }}</q-badge></q-td></template>
          <template #no-data><div class="empty-state"><q-icon name="history_edu" /><strong>Belum ada riwayat hafalan</strong><span>Simpan setoran pertama dari tab Catat Murojaah.</span></div></template>
        </q-table>
      </q-card></q-tab-panel>

      <q-tab-panel name="master" class="panel-reset"><q-card flat class="surface import-card">
        <div class="import-copy"><div class="import-icon"><q-icon name="upload_file" /></div><div><span>MASTER DATA</span><h2>Import surat dan ayat</h2><p>Unggah data Al-Qur’an berformat JSON atau CSV. Surat yang sudah ada akan diperbarui berdasarkan nomor.</p></div></div>
        <div class="import-zone" @dragover.prevent @drop.prevent="handleDrop"><q-icon name="cloud_upload" /><strong>Tarik file ke sini</strong><span>atau pilih file dari perangkat · maks. 10 MB</span><q-file v-model="importFile" accept=".json,.csv,application/json,text/csv" outlined dense label="Pilih file" class="file-picker" /></div>
        <div class="import-actions"><div><q-icon name="info_outline" /> Kolom wajib: surah_number, surah_name, ayah_number, arabic_text</div><q-btn unelevated no-caps label="Mulai import" icon="publish" class="save-btn" :disable="!importFile" :loading="importing" @click="importQuran" /></div>
        <q-banner v-if="importSummary" rounded class="success-banner"><q-icon name="task_alt" /> {{ importSummary }}</q-banner>
      </q-card></q-tab-panel>
    </q-tab-panels>
  </main>
</template>

<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useQuasar } from 'quasar'
import { supabase } from '../lib/supabase'
const props = defineProps({ profile: { type: Object, required: true } })
const $q = useQuasar(), tab = ref('murajaah'), saving = ref(false), importing = ref(false), loadingRecords = ref(false), loadingStudents = ref(false)
const records = ref([]), allStudents = ref([]), students = ref([]), search = ref(''), importFile = ref(null), importSummary = ref('')
const canImport = computed(() => ['super_administrator','administrator','pengurus'].includes(props.profile.role))
const today = new Date().toISOString().slice(0,10)
const form = reactive({ anggota_id:null,surah_number:null,ayah_start:1,ayah_end:1,review_date:today,result:'lancar',notes:'' })
const resultOptions = [{label:'Lancar',value:'lancar'},{label:'Perlu diulang',value:'ulang'},{label:'Belum lancar',value:'belum_lancar'}]
const surahNames = ['Al-Fatihah','Al-Baqarah','Ali Imran','An-Nisa','Al-Ma’idah','Al-An’am','Al-A’raf','Al-Anfal','At-Taubah','Yunus','Hud','Yusuf','Ar-Ra’d','Ibrahim','Al-Hijr','An-Nahl','Al-Isra','Al-Kahf','Maryam','Taha','Al-Anbiya','Al-Hajj','Al-Mu’minun','An-Nur','Al-Furqan','Asy-Syu’ara','An-Naml','Al-Qasas','Al-Ankabut','Ar-Rum','Luqman','As-Sajdah','Al-Ahzab','Saba','Fatir','Yasin','As-Saffat','Sad','Az-Zumar','Gafir','Fussilat','Asy-Syura','Az-Zukhruf','Ad-Dukhan','Al-Jasiyah','Al-Ahqaf','Muhammad','Al-Fath','Al-Hujurat','Qaf','Az-Zariyat','At-Tur','An-Najm','Al-Qamar','Ar-Rahman','Al-Waqi’ah','Al-Hadid','Al-Mujadilah','Al-Hasyr','Al-Mumtahanah','As-Saff','Al-Jumu’ah','Al-Munafiqun','At-Tagabun','At-Talaq','At-Tahrim','Al-Mulk','Al-Qalam','Al-Haqqah','Al-Ma’arij','Nuh','Al-Jinn','Al-Muzzammil','Al-Muddassir','Al-Qiyamah','Al-Insan','Al-Mursalat','An-Naba','An-Nazi’at','Abasa','At-Takwir','Al-Infitar','Al-Mutaffifin','Al-Insyiqaq','Al-Buruj','At-Tariq','Al-A’la','Al-Gasyiyah','Al-Fajr','Al-Balad','Asy-Syams','Al-Lail','Ad-Duha','Asy-Syarh','At-Tin','Al-Alaq','Al-Qadr','Al-Bayyinah','Az-Zalzalah','Al-Adiyat','Al-Qari’ah','At-Takasur','Al-Asr','Al-Humazah','Al-Fil','Quraisy','Al-Ma’un','Al-Kausar','Al-Kafirun','An-Nasr','Al-Lahab','Al-Ikhlas','Al-Falaq','An-Nas']
const counts=[7,286,200,176,120,165,206,75,129,109,123,111,43,52,99,128,111,110,98,135,112,78,118,64,77,227,93,88,69,60,34,30,73,54,45,83,182,88,75,85,54,53,89,59,37,35,38,29,18,45,60,49,62,55,78,96,29,22,24,13,14,11,11,18,12,12,30,52,52,44,28,28,20,56,40,31,50,40,46,42,29,19,36,25,22,17,19,26,30,20,15,21,11,8,8,19,5,8,8,11,11,8,3,9,5,4,7,3,6,3,5,4,5,6]
const arabic=['الفاتحة','البقرة','آل عمران','النساء','المائدة','الأنعام','الأعراف','الأنفال','التوبة','يونس','هود','يوسف','الرعد','إبراهيم','الحجر','النحل','الإسراء','الكهف','مريم','طه']
const surahs=surahNames.map((name,i)=>({number:i+1,name,arabic:arabic[i]||'',ayah_count:counts[i]}))
const allSurahOptions=surahs.map(s=>({label:`${s.number}. ${s.name}${s.arabic?` · ${s.arabic}`:''}`,value:s.number})), surahOptions=ref(allSurahOptions)
const selectedSurah=computed(()=>surahs.find(s=>s.number===form.surah_number)), uniqueStudents=computed(()=>new Set(records.value.map(r=>r.anggota_id)).size), passedCount=computed(()=>records.value.filter(r=>r.result==='lancar').length)
const columns=[{name:'date',label:'Tanggal',field:'review_date',align:'left',sortable:true,format:v=>new Intl.DateTimeFormat('id-ID',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(`${v}T00:00:00`))},{name:'student',label:'Santri',field:'student_name',align:'left',sortable:true},{name:'surah',label:'Surat & ayat',field:'surah_number',align:'left'},{name:'result',label:'Hasil',field:'result',align:'left'},{name:'notes',label:'Catatan',field:'notes',align:'left'}]
const filteredRecords=computed(()=>{const q=search.value?.toLowerCase().trim();return q?records.value.filter(r=>`${r.student_name} ${surahName(r.surah_number)} ${r.notes||''}`.toLowerCase().includes(q)):records.value})
const required=v=>!!v||'Wajib diisi', verseRules=[v=>Number(v)>=1||'Minimal ayat 1',v=>!selectedSurah.value||Number(v)<=selectedSurah.value.ayah_count||`Maksimal ${selectedSurah.value.ayah_count}`], endVerseRules=[...verseRules,v=>Number(v)>=Number(form.ayah_start)||'Tidak boleh sebelum ayat awal']
function normalizeVerses(){form.ayah_start=1;form.ayah_end=selectedSurah.value?.ayah_count||1} function filterSurahs(v,u){u(()=>{const q=v.toLowerCase();surahOptions.value=allSurahOptions.filter(s=>s.label.toLowerCase().includes(q))})} function filterStudents(v,u){u(()=>{const q=v.toLowerCase();students.value=allStudents.value.filter(s=>s.label.toLowerCase().includes(q))})}
function surahName(n){return surahs.find(s=>s.number===Number(n))?.name||`Surat ${n}`} function resultLabel(v){return resultOptions.find(r=>r.value===v)?.label||v} function initialsOf(n=''){return n.split(' ').slice(0,2).map(p=>p[0]).join('').toUpperCase()}
async function loadStudents(){loadingStudents.value=true;const {data,error}=await supabase.from('anggota').select('id,name,masjid_id').eq('member_role','murid').eq('membership_status','active').order('name');if(!error){allStudents.value=(data||[]).map(s=>({label:s.name,value:s.id,masjid_id:s.masjid_id}));students.value=allStudents.value}loadingStudents.value=false}
async function loadRecords(){loadingRecords.value=true;const {data,error}=await supabase.from('murojaah_records').select('*, anggota(name)').order('review_date',{ascending:false}).order('created_at',{ascending:false});if(!error)records.value=(data||[]).map(r=>({...r,student_name:r.anggota?.name||'Santri'}));loadingRecords.value=false}
async function saveRecord(){saving.value=true;const student=allStudents.value.find(s=>s.value===form.anggota_id);if(!student?.masjid_id){saving.value=false;return $q.notify({type:'negative',message:'Santri belum terhubung ke masjid.'})}const {error}=await supabase.from('murojaah_records').insert({...form,masjid_id:student.masjid_id,recorded_by:props.profile.auth_user_id});saving.value=false;if(error)return $q.notify({type:'negative',message:error.code==='42501'?'Akun Anda tidak memiliki akses untuk mencatat murojaah santri ini. Muat ulang setelah policy Supabase diperbarui.':error.message});$q.notify({type:'positive',message:'Murojaah berhasil disimpan'});Object.assign(form,{anggota_id:null,surah_number:null,ayah_start:1,ayah_end:1,review_date:today,result:'lancar',notes:''});await loadRecords();tab.value='history'}
function handleDrop(e){const f=e.dataTransfer.files?.[0];if(f)importFile.value=f} function parseCsv(t){const [h,...l]=t.trim().split(/\r?\n/),k=h.split(',').map(v=>v.trim());return l.map(x=>Object.fromEntries(x.split(',').map((v,i)=>[k[i],v.trim()]))) }
async function importQuran(){importing.value=true;importSummary.value='';try{const text=await importFile.value.text(),raw=importFile.value.name.endsWith('.json')?JSON.parse(text):parseCsv(text),items=Array.isArray(raw)?raw:(raw.ayahs||[]);if(!items.length)throw new Error('File tidak memuat data ayat.');const grouped=new Map();items.forEach(a=>{const n=Number(a.surah_number);if(!grouped.has(n))grouped.set(n,{number:n,name:a.surah_name||surahName(n),arabic_name:a.surah_arabic||null,ayah_count:0});grouped.get(n).ayah_count=Math.max(grouped.get(n).ayah_count,Number(a.ayah_number))});let {error}=await supabase.from('quran_surahs').upsert([...grouped.values()],{onConflict:'number'});if(error)throw error;const ayahs=items.map(a=>({surah_number:Number(a.surah_number),ayah_number:Number(a.ayah_number),arabic_text:a.arabic_text,translation:a.translation||null}));({error}=await supabase.from('quran_ayahs').upsert(ayahs,{onConflict:'surah_number,ayah_number'}));if(error)throw error;importSummary.value=`${grouped.size} surat dan ${ayahs.length} ayat berhasil diimport.`;importFile.value=null;$q.notify({type:'positive',message:'Data Al-Qur’an berhasil diperbarui'})}catch(e){$q.notify({type:'negative',message:e.message||'File gagal diimport'})}finally{importing.value=false}}
onMounted(()=>Promise.all([loadStudents(),loadRecords()]))
</script>

<style scoped>
