@media(max-width:900px){.quran-hero{align-items:flex-start;flex-direction:column}.hero-stats{width:100%;justify-content:space-between;padding-top:18px;border-top:1px solid rgba(255,255,255,.12)}.workspace-grid{grid-template-columns:1fr}.side-column{display:grid;grid-template-columns:1fr 1fr}}
@media(max-width:600px){.quran-hero{padding:23px}.hero-icon{display:none}.hero-copy p{font-size:12px}.hero-stats{gap:12px}.quran-tabs{display:flex;overflow-x:auto}.quran-tabs :deep(.q-tab){padding:0 11px}.murajaah-form{grid-template-columns:1fr}.field{grid-column:1/-1}.side-column{display:flex}.history-card,.form-card,.import-card{padding:17px}.history-head{align-items:stretch;flex-direction:column;gap:14px}.history-head .q-input{width:100%}.import-copy{align-items:flex-start}.import-actions{align-items:stretch;flex-direction:column}}
